#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>
struct device {int valid;};struct device_attribute {int unused;};struct kgsl_device {int mutex;struct {unsigned long interval_timeout;} pwrctrl;};
enum kgsl_pwrctrl_timer_type {KGSL_PWR_IDLE_TIMER};
static struct kgsl_device gpu;static int parses,locks;
static struct kgsl_device *kgsl_device_from_dev(struct device *d){return d&&d->valid?&gpu:NULL;}
static int kgsl_sysfs_store(const char *s,unsigned *v){char *end;unsigned long long n;parses++;if(*s=='-')return -EINVAL;errno=0;n=strtoull(s,&end,0);if(end==s)return -EINVAL;if(*end=='\n')end++;if(*end)return -EINVAL;if(errno||n>UINT_MAX)return -ERANGE;*v=n;return 0;}
/* 100Hz conversion for these small values; range test limit is a fixture. */
#define MAX_JIFFY_OFFSET 100000UL
#define jiffies_to_usecs(j) ((j)*10000UL)
#define msecs_to_jiffies(ms) (((unsigned long)(ms)+9UL)/10UL)
#define mutex_lock(p) (++locks)
#define mutex_unlock(p) ((void)0)
static ssize_t native(struct device *dev, struct device_attribute *attr,
					const char *buf, size_t count,
					enum kgsl_pwrctrl_timer_type timer)
{
	unsigned int val = 0;
	struct kgsl_device *device = kgsl_device_from_dev(dev);
	int ret;

	if (device == NULL)
		return 0;

	ret = kgsl_sysfs_store(buf, &val);
	if (ret)
		return ret;

	/*
	 * We don't quite accept a maximum of 0xFFFFFFFF due to internal jiffy
	 * math, so make sure the value falls within the largest offset we can
	 * deal with
	 */

	if (val > jiffies_to_usecs(MAX_JIFFY_OFFSET))
		return -EINVAL;

	mutex_lock(&device->mutex);
	/* Let the timeout be requested in ms, but convert to jiffies. */
	if (timer == KGSL_PWR_IDLE_TIMER)
		device->pwrctrl.interval_timeout = msecs_to_jiffies(val);

	mutex_unlock(&device->mutex);

	return count;
}
static ssize_t donor(struct device *dev, struct device_attribute *attr,
					const char *buf, size_t count,
					enum kgsl_pwrctrl_timer_type timer)
{
	unsigned int val = 0;
	struct kgsl_device *device = kgsl_device_from_dev(dev);
	int ret;

	return count;
	if (device == NULL)
		return 0;

	ret = kgsl_sysfs_store(buf, &val);
	if (ret)
		return ret;

	/*
	 * We don't quite accept a maximum of 0xFFFFFFFF due to internal jiffy
	 * math, so make sure the value falls within the largest offset we can
	 * deal with
	 */

	if (val > jiffies_to_usecs(MAX_JIFFY_OFFSET))
		return -EINVAL;

	mutex_lock(&device->mutex);
	/* Let the timeout be requested in ms, but convert to jiffies. */
	if (timer == KGSL_PWR_IDLE_TIMER)
		device->pwrctrl.interval_timeout = msecs_to_jiffies(val);

	mutex_unlock(&device->mutex);

	return count;
}

int main(void){const char *inputs[]={"58\n","200\n","0\n","bad\n","4294967296\n"};int v,c;struct device d={1};for(v=0;v<2;v++)for(c=0;c<6;c++){const char *s=inputs[c<5?c:0];size_t n=0;ssize_t ret;while(s[n])n++;gpu.pwrctrl.interval_timeout=7;parses=locks=0;d.valid=c!=5;ret=v?donor(&d,NULL,s,n,KGSL_PWR_IDLE_TIMER):native(&d,NULL,s,n,KGSL_PWR_IDLE_TIMER);printf("%s case=%d ret=%ld ticks=%lu parses=%d locks=%d\n",v?"donor":"native",c,(long)ret,gpu.pwrctrl.interval_timeout,parses,locks);}return 0;}
